mkdir -p /tmp/fanin && cd /tmp/fanin && cat > main.go <<'EOF'
package main

import (
	"fmt"
	"go/ast"
	"go/types"
	"os"
	"sort"
	"strings"

	"golang.org/x/tools/go/packages"
)

type key struct {
	name string
	pos  string
}

func main() {
	cfg := &packages.Config{
		Mode:  packages.NeedName | packages.NeedFiles | packages.NeedSyntax | packages.NeedTypes | packages.NeedTypesInfo | packages.NeedDeps | packages.NeedImports,
		Dir:   os.Args[1],
		Tests: true,
	}
	pkgs, err := packages.Load(cfg, "./...")
	if err != nil {
		panic(err)
	}
	callSites := map[key]int{}
	callerFuncs := map[key]map[string]bool{}
	seenFile := map[string]bool{}
	for _, p := range pkgs {
		if p.TypesInfo == nil {
			continue
		}
		for _, f := range p.Syntax {
			fname := p.Fset.Position(f.Pos()).Filename
			if seenFile[fname] {
				continue
			}
			seenFile[fname] = true
			// track enclosing func
			var stack []string
			ast.Inspect(f, func(n ast.Node) bool {
				switch d := n.(type) {
				case *ast.FuncDecl:
					stack = append(stack, fmt.Sprintf("%s:%s", fname, d.Name.Name))
				case *ast.CallExpr:
					var id *ast.Ident
					switch fn := d.Fun.(type) {
					case *ast.Ident:
						id = fn
					case *ast.SelectorExpr:
						id = fn.Sel
					}
					if id == nil {
						return true
					}
					obj := p.TypesInfo.Uses[id]
					if obj == nil {
						return true
					}
					fnObj, ok := obj.(*types.Func)
					if !ok {
						return true
					}
					pos := p.Fset.Position(fnObj.Pos())
					if pos.Filename == "" {
						return true
					}
					k := key{name: fullName(fnObj), pos: pos.Filename + ":" + fmt.Sprint(pos.Line)}
					callSites[k]++
					if callerFuncs[k] == nil {
						callerFuncs[k] = map[string]bool{}
					}
					enc := "<top>:" + fname
					if len(stack) > 0 {
						enc = stack[len(stack)-1]
					}
					callerFuncs[k][enc] = true
				}
				return true
			})
		}
	}
	type row struct {
		k     key
		sites int
		fns   int
	}
	var rows []row
	for k, v := range callSites {
		if !strings.Contains(k.pos, "/internal/") {
			continue
		}
		rows = append(rows, row{k, v, len(callerFuncs[k])})
	}
	sort.Slice(rows, func(i, j int) bool { return rows[i].sites > rows[j].sites })
	for i, r := range rows {
		if i > 34 {
			break
		}
		fmt.Printf("%4d sites %4d distinct-callers  %s  @ %s\n", r.sites, r.fns, r.k.name, r.k.pos)
	}
}

func fullName(f *types.Func) string {
	sig, _ := f.Type().(*types.Signature)
	recv := ""
	if sig != nil && sig.Recv() != nil {
		recv = "(" + sig.Recv().Type().String() + ")."
	}
	pkg := ""
	if f.Pkg() != nil {
		pkg = f.Pkg().Name() + "."
	}
	return pkg + recv + f.Name()
}
EOF
